arguments.command:
$ErrorActionPreference='Continue'
Write-Output '=== lark-cli config.json apps structure (redacted) ==='
$c = Get-Content "$env:USERPROFILE\.lark-cli\config.json" -Raw | ConvertFrom-Json
$c.apps.PSObject.Properties | ForEach-Object {
  $n = $_.Name; $v = $_.Value
  Write-Output "APP: $n"
  $v.PSObject.Properties | ForEach-Object {
    $val = $_.Value
    if ($val -is [string] -and $val.Length -gt 12) { $val = $val.Substring(0,6) + '***(len=' + $val.Length + ')' }
    Write-Output ("  " + $_.Name + " = " + $val)
  }
}
Write-Output '=== token store files ==='
Get-ChildItem "$env:USERPROFILE\.lark-cli" -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'token|auth|cred|secret' } | Select-Object FullName, Length

$ErrorActionPreference='Continue'
$c = Get-Content "$env:USERPROFILE\.lark-cli\config.json" -Raw | ConvertFrom-Json
Write-Output '=== apps raw (structure only, values redacted) ==='
foreach ($p in $c.apps.PSObject.Properties) {
  $n = $p.Name
  $v = $p.Value
  Write-Output "APPKEY: $n  type=$($v.GetType().Name)"
  if ($v -is [System.Array]) {
    Write-Output "  array count=$($v.Count)"
    foreach ($item in $v) {
      foreach ($ip in $item.PSObject.Properties) {
        $val = $ip.Value
        if ($val -is [string] -and $val.Length -gt 10) { $val = $val.Substring(0,5) + '***' }
        Write-Output ("   " + $ip.Name + " = " + $val)
      }
      Write-Output '   ---'
    }
  }
}

