		t.Fatalf("期望 ErrForbidden，实际 %v", err)
	}
	if err := AuthorizeOps(cred); !errors.Is(err, domain.ErrForbidden) {
		t.Fatalf("期望 ErrForbidden，实际 %v", err)
	}
}

