// TestNewFallsBackToSystemClock 验证未提供时钟时使用系统时钟。
func TestNewFallsBackToSystemClock(t *testing.T) {
	svc, _, db := newTestService(t)
	plain := New(db, nil, &fakeUpstream{})
	if plain.Clock() == nil {
		t.Fatalf("时钟不应为空")
	}
