arguments.old_string:
def coverage(repo: Path, min_cov: int) -> dict:
    profile = repo / ".quota-guard-coverage.out"
    cmd = [
        "go", "test",
        "./internal/domain/...", "./internal/store/...", "./internal/service/...",
        "-coverprofile", str(profile), "-count=1",
    ]
    code, out = run(cmd, repo)
    result = {"ok": False, "packages": {}, "command": " ".join(cmd), "output": out.strip()[-2000:]}
    if code != 0:
        result["error"] = "覆盖率采集失败"
        return result
    func_code, func_out = run(
        ["go", "tool", "cover", "-func", str(profile)], repo
    )
    if func_code != 0:
        result["error"] = "无法解析覆盖率报告"
        return result
    total_by_pkg: dict[str, list[float]] = {}
    for line in func_out.splitlines():
        m = re.match(r"modelquota/internal/(\w+)/", line)
        if not m:
            continue
        tail = line.strip().split("\t")[-1]
        if not tail.endswith("%"):
            continue
        try:
            pct = float(tail[:-1])
        except ValueError:
            continue
        total_by_pkg.setdefault(m.group(1), []).append(pct)
    ok = True
    for pkg in CORE_PACKAGES:
        vals = total_by_pkg.get(pkg, [])
        if not vals:
            result["packages"][pkg] = None
            ok = False
            continue
        # 用「未覆盖语句占比」反推包级覆盖率，取各函数中最低值作为保守估计。
        lowest = min(vals)
        result["packages"][pkg] = round(lowest, 1)
        if lowest < min_cov:
            ok = False
    result["ok"] = ok
    try:
        profile.unlink()
    except OSError:
        pass
    return result

